@page "/shipments"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch - Manage Shipments</PageTitle>

<h2>Shipment Management</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status:</label>
        <select class="form-select" @onchange="OnStatusFilterChanged">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-primary" @onclick="ShowAddForm">Add New Shipment</button>
    </div>
</div>

@if (showAddForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Tracking Number" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-3 d-flex align-items-end gap-2">
                    <button class="btn btn-success" @onclick="AddShipment">Save</button>
                    <button class="btn btn-secondary" @onclick="CancelAdd">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in shipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </td>
                    <td>@shipment.CustomerEmail</td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private bool showAddForm;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(5) };

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString();
        if (string.IsNullOrEmpty(value))
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        else if (Enum.TryParse<ShipmentStatus>(value, out var status))
        {
            shipments = await ShipmentService.GetShipmentsByStatusAsync(status);
        }
    }

    private void ShowAddForm() => showAddForm = true;
    private void CancelAdd() => showAddForm = false;

    private async Task AddShipment()
    {
        newShipment.Status = ShipmentStatus.Pending;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(5) };
        showAddForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Your Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., ST-2024-001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with that tracking number, or it does not belong to your account.
    </div>
}
else if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5>Shipment: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Estimated Delivery</dt>
                        <dd>@shipment.EstimatedDelivery.ToLongDateString()</dd>
                        <dt>Actual Delivery</dt>
                        <dd>@(shipment.ActualDelivery?.ToLongDateString() ?? "Not yet delivered")</dd>
                        <dt>Created</dt>
                        <dd>@shipment.CreatedAt.ToLongDateString()</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

<h3 class="mt-5">Your Shipments</h3>

@if (customerShipments is null)
{
    <p>Loading your shipments...</p>
}
else if (customerShipments.Count == 0)
{
    <p>You have no shipments associated with your account.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in customerShipments)
            {
                <tr>
                    <td><a href="javascript:void(0)" @onclick="() => TrackSpecific(s.TrackingNumber)">@s.TrackingNumber</a></td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private List<Shipment>? customerShipments;
    private string? userEmail;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        userEmail = authState.User.FindFirst(c => c.Type == "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name")?.Value
                    ?? authState.User.Identity?.Name;

        if (!string.IsNullOrEmpty(userEmail))
        {
            customerShipments = await ShipmentService.GetShipmentsByCustomerEmailAsync(userEmail);
        }
        else
        {
            customerShipments = [];
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searched = true;
        var result = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());

        // Only show if it belongs to the authenticated user
        if (result is not null && string.Equals(result.CustomerEmail, userEmail, StringComparison.OrdinalIgnoreCase))
        {
            shipment = result;
        }
        else
        {
            shipment = null;
        }
    }

    private async Task TrackSpecific(string tracking)
    {
        trackingNumber = tracking;
        await SearchShipment();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

