+@code {
+    private string trackingNumber = string.Empty;
+    private Shipment? shipment;
+    private bool searched;
+    private List<Shipment>? customerShipments;
+    private string? userEmail;
+
+    protected override async Task OnInitializedAsync()
+    {
+        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
+        userEmail = authState.User.FindFirst(c => c.Type == "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name")?.Value
+                    ?? authState.User.Identity?.Name;
+
+        if (!string.IsNullOrEmpty(userEmail))
+        {
+            customerShipments = await ShipmentService.GetShipmentsByCustomerEmailAsync(userEmail);
