         // Only show if it belongs to the authenticated user
         if (result is not null && string.Equals(result.CustomerEmail, userEmail, StringComparison.OrdinalIgnoreCase))
         {
             shipment = result;
         }
         else
         {
             shipment = null;
         }
     }

     private async Task TrackSpecific(string tracking)
     {
         trackingNumber = tracking;
         await SearchShipment();
     }

     private async Task HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
         {
             await SearchShipment();
         }
     }

